head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.notiId;
scwin.vSecugrpID = "";
scwin.strAcptNo;
scwin.gUsrId = js_id;
scwin.vScrenID = "ULDSTF05239_FILE.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    trs_Read.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readFile&acpt_no=" + scwin.strAcptNo;
    trs_Read.KeyValue = "JSP(O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    var fileYn = "N";
    for (i = 1; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") != "") {
            fileYn = "Y";
        }
    }
    if (fileYn == "N") {
        $c.win.alert("첨부파일을 하나이상 등록해주세요");
        return;
    }
    var rtn = confirm('첨부파일을 등록 하시겠습니까?');
    if (rtn == 1) {
        // [확인] 버튼이 눌려졌을 경우		
        trs_Save.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createFile&acpt_no=" + scwin.strAcptNo + "&usr_id=" + scwin.gUsrId;
        trs_Save.KeyValue = "JSP(I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    for (i = 0; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") == "" && dts_fileList.getCellData(i, "filename") == "") {
            $c.cp.removeRow(dts_fileList, i);
        }
    }
    if (dts_fileList.getTotalRow() == 0) {
        $c.win.alert("첨부파일을 한개이상  입력해주세요.");
        return;
    }
    var rtn = confirm('첨부파일을 수정 하시겠습니까?');
    if (rtn == 1) {
        // [확인] 버튼이 눌려졌을 경우		
        trs_Update.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=modifyFile&acpt_no=" + scwin.strAcptNo + "&usr_id=" + scwin.gUsrId;
        trs_Update.KeyValue = "JSP(I:pInput2=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('첨부파일을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        for (i = 0; i <= dts_fileList.getTotalRow(); i++) {
            $c.cp.removeRow(dts_fileList, i);
        }
        trs_Delete.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=removeFile&acpt_no=" + scwin.strAcptNo;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_fileList)";
        trs_Delete.Post();
    }
};


//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + scwin.strAcptNo + "&attach_seq=" + attach_seq + "&gubun=32";
};
scwin.fn_setDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.trs_Read_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일등록"));
    await $c.frame.CloseFrame();
    //self.close();

};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일등록"));
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일수정"));
    await $c.frame.CloseFrame();
    //self.close();

};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일수정"));
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일삭제"));
};
scwin.grd_userlist_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        $c.elw.fn_filedown(dts_fileList.getCellData(row, "SEQ"));
    }
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    if (scwin.notiId == "input") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        //dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (scwin.notiId == "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            //dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
            file_name.setValue(inf_find.getValue());
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame(); //self.close();

};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    buttonSet.setSaveInfo(btn_save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_modify, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_delete, fn_delete); // 삭제

    setInsertReadyStatus = "I";
    scwin.strAcptNo = $c.stf.getQuery(frame.srcUrl, "ACPT_NO");
    scwin.fn_read();

    //alert("dts_fileList.CountRow-->"+dts_fileList.CountRow);
    //기존파일이 없으면
    if (dts_fileList.getTotalRow() == 0) {
        buttonSet.setInsertStatus();
        scwin.fn_setDataHeader();
    } else {
        buttonSet.setUpdateStatus();
    }
};
